create unique index if not exists basilisk_acquisition_source_identity
on public.basilisk_facilities(tenant_id,(payload #>> '{acquisition,source_id}'))
where payload #>> '{acquisition,source_id}' is not null;
create index if not exists basilisk_featured_acquisition_lookup
on public.basilisk_facilities(tenant_id,(payload #>> '{acquisition,featured_order}'));

