   select count(*) into candidates from public.basilisk_facilities
   where tenant_id=workspace.id and (site_key=seed->>'site_key'
    or (lower(trim(payload->>'address'))=lower(trim(seed #>> '{payload,address}')) and lower(trim(payload->>'city'))=lower(trim(seed #>> '{payload,city}')) and payload->>'state'=seed #>> '{payload,state}')
    or payload #>> '{acquisition,source_id}'=seed #>> '{payload,acquisition,source_id}');
   if candidates>1 then raise exception 'Conflicting acquisition address/source identities in workspace %; resolve before migration',workspace.id; end if;
   select * into existing from public.basilisk_facilities
   where tenant_id=workspace.id and (site_key=seed->>'site_key'
    or (lower(trim(payload->>'address'))=lower(trim(seed #>> '{payload,address}')) and lower(trim(payload->>'city'))=lower(trim(seed #>> '{payload,city}')) and payload->>'state'=seed #>> '{payload,state}')
    or payload #>> '{acquisition,source_id}'=seed #>> '{payload,acquisition,source_id}') limit 1;
   if found then
    -- Existing reviewed acquisition data is authoritative. Only ensure its pin is retained.
    if existing.payload->'acquisition' is null or existing.payload->'acquisition'='null'::jsonb then
     select coalesce(jsonb_agg(e),'[]'::jsonb) into merged_evidence
     from jsonb_array_elements(coalesce(seed #> '{payload,evidence}','[]'::jsonb)) e
     where not exists(select 1 from jsonb_array_elements(coalesce(existing.payload->'evidence','[]'::jsonb)) old where old->>'id'=e->>'id');
     merged_payload=existing.payload || jsonb_build_object('acquisition',seed #> '{payload,acquisition}',
      'evidence',coalesce(existing.payload->'evidence','[]'::jsonb)||merged_evidence);
    else merged_payload=existing.payload; end if;
    merged_payload=jsonb_set(merged_payload,'{acquisition,featured_order}',seed #> '{payload,acquisition,featured_order}');
    if merged_payload is distinct from existing.payload then
     update public.basilisk_facilities set payload=merged_payload,version=version+1,updated_at=now() where id=existing.id;
    end if;
   else
    merged_payload=jsonb_set(seed->'payload','{id}',to_jsonb(workspace.id::text||':'||(seed #>> '{payload,id}')));
    insert into public.basilisk_facilities(id,tenant_id,site_key,payload)
    values(merged_payload->>'id',workspace.id,seed->>'site_key',merged_payload);
   end if;
  end loop;
